class Solution:
    def countNumbersWithUniqueDigits(self, n: int) -> int:
        if n == 0:
            return 1
        res = 10
        unique_digits = 9
        available = 9
        for _ in range(2, min(n + 1, 11)):
            unique_digits *= available
            res += unique_digits
            available -= 1
        return res

class Solution {
public:
    int countNumbersWithUniqueDigits(int n) {
        if (n == 0) return 1;
        int res = 10;
        int uniqueDigits = 9;
        int available = 9;
        for (int i = 2; i <= min(n, 10); i++) {
            uniqueDigits *= available;
            res += uniqueDigits;
            available--;
        }
        return res;
    }
};

